/**
 * Single source of truth for site-wide SEO data.
 *
 * The route table below drives three things that must never disagree:
 *   1. per-route <title>/<meta> tags (via each route module's `meta` export)
 *   2. the `prerender` list in react-router.config.ts
 *   3. the generated sitemap.xml
 *
 * Adding a page means adding one entry here.
 */

export const SITE = {
  name: "Gidev Innovations",
  /** No trailing slash. Used to build canonical + og:url values. */
  url: "https://gidevtech.com",
  locale: "en_KE",
  /** Generated by scripts/optimize-images.mjs from the logo kit. */
  ogImage: "/og-image.png",
  ogImageWidth: "1200",
  ogImageHeight: "630",
} as const;

/**
 * Name / address / contact details. Schema, footer and contact page all read
 * from here so the NAP stays identical everywhere (Google Business Profile
 * must match it exactly).
 *
 * Phone, WhatsApp and email are intentionally not published yet. When they
 * are, add them here and they will flow into the footer and JSON-LD.
 */
export const BUSINESS = {
  legalName: "Gidev Innovations",
  founder: "Joseph Macharia",
  locality: "Nairobi",
  region: "Nairobi County",
  country: "KE",
  countryName: "Kenya",
  // TODO(human): set real hours, e.g. "Mon–Fri, 9:00–18:00 EAT". Hidden while null.
  hours: null as string | null,
  areaServed: ["Nairobi", "Kenya", "East Africa", "Remote worldwide"],
  // TODO(human): add the business's own profile URLs (LinkedIn, X, Instagram). Shown in the footer and schema; hidden while empty.
  sameAs: [] as string[],
  /**
   * TODO(human): WhatsApp number in international format, e.g. "+254712345678".
   * Shown only as the contact-form fallback when a Web3Forms send fails;
   * while null, that fallback points to the booking calendar instead.
   */
  whatsappNumber: null as string | null,
  calendlyUrl: "https://calendly.com/gidevtech/30min",
  callLength: "30-minute",
} as const;

export type SiteRoute = {
  path: string;
  title: string;
  description: string;
  /** sitemap.xml <priority> */
  priority: string;
  /** sitemap.xml <changefreq> */
  changefreq: "daily" | "weekly" | "monthly" | "yearly";
};

/**
 * Static routes that get pre-rendered to HTML at build time.
 *
 * Descriptions are intentionally specific — a distinct description per page is
 * what stops search engines collapsing them as duplicates.
 */
